import type { NextConfig } from 'next';

const nextConfig: NextConfig = {
  // Required by the Dockerfile: the runtime stage copies .next/standalone, which only exists with this.
  output: 'standalone',
};

export default nextConfig;

import { NextResponse } from 'next/server';

/**
 * Liveness for the container HEALTHCHECK, CI and scripts/rebuild-and-verify.sh.
 *
 * Deliberately does NOT touch the database: this answers "is the process serving?", and a DB hiccup
 * must not make the orchestrator kill a healthy app. Add a separate /api/ready for deep readiness
 * (a `SELECT 1`) when something actually needs to distinguish the two.
 *
 * It stays OPEN — never put this endpoint behind auth, or nothing can check it.
 */
export function GET(): NextResponse {
  return NextResponse.json({ ok: true });
}

# Knowledge log — &lt;app&gt;

> Architecture decisions and the _why_, recorded so the next session does not re-derive them.
> Append-only, **newest on top**. Record only the non-obvious: a decision a reasonable person would
> make differently, a trap that cost real time, a tradeoff that was actually weighed.
>
> Not a changelog. "Added a settings page" belongs in git; "settings are a single row because a
> per-key table made every read a join and nothing ever needed the flexibility" belongs here.
>
> Standard: `platform/standards/documentation.md`. Written as you go, or by `/session-wrap` at the end
> of a pass.

---

## &lt;YYYY-MM-DD&gt; — &lt;the decision, as a claim&gt;

**Context:** &lt;what forced a choice&gt;
**Decision:** &lt;what was chosen&gt;
**Why:** &lt;the reasoning, including what was rejected and what it would have cost&gt;
**Watch out:** &lt;the trap this creates for the next person&gt;

---

_(Add new decisions above this line, newest on top.)_

{
  "_readme": "Per-repo configuration for the shared gate tests installed from commons (@thiengthb/test-*). Keeping it here means the test files stay byte-identical to the registry copies — an exception is data, never an edit to the check. Prefer an inline `rulebook-allow: <rule-id> — <reason>` directive in the code itself; that one sentence satisfies both the generation-time hook and the test. The lists below are for a burn-down at install time, on an app that already has drift.",
  "no-emoji": {
    "roots": ["app", "components", "lib"],
    "allow": []
  },
  "ci-hardening": {
    "_note": "strict:true additionally requires a commit SHA for the first-party actions/* and docker/* namespaces. Off by default because that is where the published guidance draws the line and pinning them forfeits automatic patches; turn it on to take the stronger position.",
    "strict": false,
    "trustedOwners": ["actions", "github", "docker"],
    "allow": []
  }
}
